using System.Diagnostics;
using OpenCvSharp;
using OpenCvSharp.Extensions;
namespace ConquerLootClicker;

public sealed class MainForm : Form
{
 readonly TextBox adb=new(){Width=360}; readonly Button connect=new(){Text="Connect / Detect"}, capture=new(){Text="Capture LDPlayer screen"}, selAttack=new(){Text="Select Attack"}, selLoot=new(){Text="Select Loot"}, start=new(){Text="Start"}, stop=new(){Text="Stop",Enabled=false};
 readonly CheckBox attackOn=new(){Text="Attack",Checked=true,AutoSize=true}, lootOn=new(){Text="Loot",Checked=true,AutoSize=true};
 readonly NumericUpDown threshold=new(){Minimum=60,Maximum=98,Value=84,Width=60}; readonly PictureBox view=new(){Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.FromArgb(30,30,30)};
 readonly Label status=new(){AutoSize=true}; readonly System.Windows.Forms.Timer timer=new(){Interval=450};
 string? device, selecting; Mat? screen; Bitmap? bitmap; Template? attack,loot; System.Drawing.Point? drag; Rectangle dragBox; bool running; DateTime lastA=DateTime.MinValue,lastL=DateTime.MinValue;
 record Template(Mat Mat,Rectangle Rect);
 public MainForm(){Text="Conquer Classic - LDPlayer Auto Clicker";Width=1050;Height=760;MinimumSize=new System.Drawing.Size(820,580);
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Padding=new Padding(8)};root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));Controls.Add(root);
  var r1=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill};r1.Controls.Add(new Label{Text="ADB path",AutoSize=true,Padding=new Padding(0,7,0,0)});adb.Text=FindAdb();r1.Controls.Add(adb);var browse=new Button{Text="Browse"};browse.Click+=(_,_)=>{using var d=new OpenFileDialog{Filter="adb.exe|adb.exe|All files|*.*"};if(d.ShowDialog()==DialogResult.OK)adb.Text=d.FileName;};r1.Controls.Add(browse);r1.Controls.Add(connect);root.Controls.Add(r1,0,0);
  var r2=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,Padding=new Padding(0,7,0,7)};foreach(var c in new Control[]{capture,selAttack,selLoot,attackOn,lootOn,new Label{Text="Match %",AutoSize=true,Padding=new Padding(5,7,0,0)},threshold,start,stop})r2.Controls.Add(c);root.Controls.Add(r2,0,1);root.Controls.Add(view,0,2);root.Controls.Add(status,0,3);
  connect.Click+=(_,_)=>Connect();capture.Click+=(_,_)=>Capture();selAttack.Click+=(_,_)=>Begin("Attack");selLoot.Click+=(_,_)=>Begin("Loot");start.Click+=(_,_)=>StartRun();stop.Click+=(_,_)=>StopRun();view.MouseDown+=Down;view.MouseMove+=Move;view.MouseUp+=Up;view.Paint+=PaintOverlay;timer.Tick+=async(_,_)=>await Tick();FormClosing+=(_,_)=>{timer.Stop();screen?.Dispose();bitmap?.Dispose();attack?.Mat.Dispose();loot?.Mat.Dispose();};status.Text="Open LDPlayer and connect.";
 }
 static string FindAdb(){string[] p={@"C:\LDPlayer\LDPlayer9\adb.exe",@"C:\Program Files\LDPlayer\LDPlayer9\adb.exe",@"C:\Program Files (x86)\LDPlayer\LDPlayer9\adb.exe",@"C:\Program Files\dnplayerext2\adb.exe"};return p.FirstOrDefault(File.Exists)??"adb";}
 Process Proc(string args,int ms=10000){var p=Process.Start(new ProcessStartInfo(adb.Text.Trim(),args){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true})??throw new Exception("Could not start ADB");if(!p.WaitForExit(ms)){p.Kill(true);throw new Exception("ADB timed out");}return p;}
 void Connect(){try{var p=Proc("devices");var lines=p.StandardOutput.ReadToEnd();var dev=lines.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Skip(1).Select(x=>x.Split(' ',StringSplitOptions.RemoveEmptyEntries)).FirstOrDefault(x=>x.Length>1&&x[1]=="device");if(dev==null){foreach(var port in new[]{5555,5557,5559,5565,62001})try{var q=Process.Start(new ProcessStartInfo(adb.Text.Trim(),$"connect 127.0.0.1:{port}"){UseShellExecute=false,CreateNoWindow=true});q?.WaitForExit(2500);}catch{}p=Proc("devices");lines=p.StandardOutput.ReadToEnd();dev=lines.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Skip(1).Select(x=>x.Split(' ',StringSplitOptions.RemoveEmptyEntries)).FirstOrDefault(x=>x.Length>1&&x[1]=="device");}if(dev==null){MessageBox.Show("No LDPlayer device found. Open LDPlayer or browse to its adb.exe.");return;}device=dev[0];status.Text="Connected: "+device;Capture();}catch(Exception e){MessageBox.Show(e.Message);}}
 Mat Screenshot(){if(device==null)throw new Exception("Connect first");var p=Process.Start(new ProcessStartInfo(adb.Text.Trim(),$"-s {device} exec-out screencap -p"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true})??throw new Exception("ADB launch failed");using var m=new MemoryStream();p.StandardOutput.BaseStream.CopyTo(m);var err=p.StandardError.ReadToEnd();if(!p.WaitForExit(10000)||p.ExitCode!=0)throw new Exception("Screenshot failed: "+err);var mat=Cv2.ImDecode(m.ToArray(),ImreadModes.Color);if(mat.Empty())throw new Exception("Invalid screenshot");return mat;}
 void Capture(){try{if(device==null){Connect();if(device==null)return;}screen?.Dispose();screen=Screenshot();bitmap?.Dispose();bitmap=BitmapConverter.ToBitmap(screen);view.Image=bitmap;status.Text=$"Captured {screen.Width} x {screen.Height}. Select target regions.";view.Invalidate();}catch(Exception e){MessageBox.Show(e.Message,"Capture error");}}
 void Begin(string n){if(screen==null)Capture();if(screen!=null){selecting=n;status.Text=$"Drag a tight rectangle around {n}.";}}
 Rectangle ToSource(Rectangle r){if(screen==null)return Rectangle.Empty;float s=Math.Min((float)view.ClientSize.Width/screen.Width,(float)view.ClientSize.Height/screen.Height);int ox=(view.ClientSize.Width-(int)(screen.Width*s))/2,oy=(view.ClientSize.Height-(int)(screen.Height*s))/2;int x=Math.Clamp((int)((r.X-ox)/s),0,screen.Width-1),y=Math.Clamp((int)((r.Y-oy)/s),0,screen.Height-1);int w=Math.Clamp((int)(r.Width/s),1,screen.Width-x),h=Math.Clamp((int)(r.Height/s),1,screen.Height-y);return new Rectangle(x,y,w,h);}
 static Rectangle Rect(System.Drawing.Point a,System.Drawing.Point b)=>new(Math.Min(a.X,b.X),Math.Min(a.Y,b.Y),Math.Abs(a.X-b.X),Math.Abs(a.Y-b.Y));
 void Down(object? s,MouseEventArgs e){if(selecting!=null)drag=e.Location;}void Move(object? s,MouseEventArgs e){if(drag.HasValue){dragBox=Rect(drag.Value,e.Location);view.Invalidate();}}
 void Up(object? s,MouseEventArgs e){if(selecting==null||!drag.HasValue||screen==null)return;dragBox=Rect(drag.Value,e.Location);var r=ToSource(dragBox);if(r.Width>=8&&r.Height>=8){var m=new Mat(screen,new OpenCvSharp.Rect(r.X,r.Y,r.Width,r.Height)).Clone();if(selecting=="Attack"){attack?.Mat.Dispose();attack=new(m,r);}else{loot?.Mat.Dispose();loot=new(m,r);}status.Text=selecting+" template saved.";}else status.Text="Selection too small; try again.";selecting=null;drag=null;view.Invalidate();}
 void PaintOverlay(object? s,PaintEventArgs e){if(screen==null)return;float sc=Math.Min((float)view.ClientSize.Width/screen.Width,(float)view.ClientSize.Height/screen.Height);int ox=(view.ClientSize.Width-(int)(screen.Width*sc))/2,oy=(view.ClientSize.Height-(int)(screen.Height*sc))/2;foreach(var t in new[]{(attack,Color.Lime,"Attack"),(loot,Color.Gold,"Loot")})if(t.Item1!=null){var r=t.Item1.Rect;using var pen=new Pen(t.Item2,2);e.Graphics.DrawRectangle(pen,ox+(int)(r.X*sc),oy+(int)(r.Y*sc),(int)(r.Width*sc),(int)(r.Height*sc));e.Graphics.DrawString(t.Item3,Font,new SolidBrush(t.Item2),ox+r.X*sc,oy+r.Y*sc);}if(drag.HasValue)using(var p=new Pen(Color.Cyan,2))e.Graphics.DrawRectangle(p,dragBox);}
 void StartRun(){if(device==null){Connect();if(device==null)return;}if((attackOn.Checked&&attack==null)||(lootOn.Checked&&loot==null)){MessageBox.Show("Capture the screen and select each enabled target.");return;}running=true;start.Enabled=false;stop.Enabled=true;timer.Start();status.Text="Running. Loot is checked before Attack. Mouse cursor will not move.";}
 void StopRun(){running=false;timer.Stop();start.Enabled=true;stop.Enabled=false;status.Text="Stopped.";}
 async Task Tick(){if(!running||device==null)return;try{using var frame=await Task.Run(Screenshot);if(lootOn.Checked&&loot!=null&&(DateTime.Now-lastL).TotalMilliseconds>800){var h=await Task.Run(()=>Find(frame,loot.Mat));if(h!=null){await Tap(h.Value.X,h.Value.Y);lastL=DateTime.Now;status.Text=$"Loot tap at {h.Value.X},{h.Value.Y} ({h.Value.Score:P0})";return;}}if(attackOn.Checked&&attack!=null&&(DateTime.Now-lastA).TotalMilliseconds>1400){var h=await Task.Run(()=>Find(frame,attack.Mat));if(h!=null){await Tap(h.Value.X,h.Value.Y);lastA=DateTime.Now;status.Text=$"Attack tap at {h.Value.X},{h.Value.Y} ({h.Value.Score:P0})";}}}catch(Exception e){StopRun();status.Text="Stopped: "+e.Message;}}
 (int X,int Y,double Score)? Find(Mat frame,Mat tpl){double best=0;OpenCvSharp.Point loc=default;double bs=1;foreach(double scale in new[]{.55,.65,.75,.85,.95,1.0,1.05,1.15,1.25,1.4,1.6,1.8}){int w=(int)(tpl.Width*scale),h=(int)(tpl.Height*scale);if(w<8||h<8||w>frame.Width||h>frame.Height)continue;using var resized=new Mat();Cv2.Resize(tpl,resized,new OpenCvSharp.Size(w,h));using var result=new Mat();Cv2.MatchTemplate(frame,resized,result,TemplateMatchModes.CCoeffNormed);Cv2.MinMaxLoc(result,out _,out double score,out _,out OpenCvSharp.Point p);if(score>best){best=score;loc=p;bs=scale;}}if(best<(double)threshold.Value/100.0)return null;return(loc.X+(int)(tpl.Width*bs)/2,loc.Y+(int)(tpl.Height*bs)/2,best);}
 async Task Tap(int x,int y){await Task.Run(()=>{var p=Process.Start(new ProcessStartInfo(adb.Text.Trim(),$"-s {device} shell input tap {x} {y}"){UseShellExecute=false,CreateNoWindow=true})??throw new Exception("Tap command failed");if(!p.WaitForExit(5000))p.Kill(true);if(p.ExitCode!=0)throw new Exception("ADB tap failed");});}
}
